package com.aoo.bcg.hall.room;
import static org.junit.jupiter.api.Assertions.*;import java.time.Duration;import java.util.*;import org.junit.jupiter.api.Test;
import com.aoo.bcg.hall.http.HallError;
final class RoomCreateSagaTest{
 @Test void completesOnceAndReturnsAuthorityLease(){Fixture f=new Fixture(0);Map<String,Object>a=f.saga.create(7,"request-00000001",request());Map<String,Object>b=f.saga.create(7,"request-00000001",request());assertEquals(a,b);assertEquals(1,f.billing.reserve);assertEquals(1,f.billing.confirm);assertEquals(1,f.rooms.register);assertEquals(1,f.authority.create);assertEquals("OPEN",a.get("state"));assertEquals(1L,a.get("fencingToken"));}
 @Test void normalizedRulesReachBillingAndHallBeforeAnySideEffect(){Fixture f=new Fixture(0,c->c.withRules(Map.of("roomDurationMinutes",30,"playerCount",8,"payerMode","OWNER")));f.saga.create(7,"request-00000021",request());assertEquals(30,f.billing.lastRules.get("roomDurationMinutes"));assertFalse(f.billing.lastRules.containsKey("rounds"));assertEquals(f.billing.lastRules,f.rooms.lastRules);assertEquals(f.billing.lastRules,f.store.command.rules());}
 @Test void onlyValidatedHallProjectionCarriesTheNormalizedMarker(){
  RoomCreateSaga.Command raw=RoomCreateSaga.Command.parse(7,"request-00000022",request());
  assertFalse(raw.normalizedRules());
  assertFalse(raw.withRules(Map.of("playerCount",2)).normalizedRules());
  assertTrue(raw.withValidatedRules(Map.of("playerCount",2)).normalizedRules());
 }
 @Test void compensatesEveryCompletedStepIdempotently(){for(int fail=1;fail<=4;fail++){final int currentFail=fail;Fixture f=new Fixture(currentFail);assertThrows(IllegalStateException.class,()->f.saga.create(7,"request-0000000"+currentFail,request()));assertEquals(currentFail>1?1:0,f.billing.release);assertEquals(currentFail>2?1:0,f.rooms.remove);assertEquals(currentFail>3?1:0,f.authority.remove);}}
 @Test void rejectsReplayDriftAuthorityFieldsAndCompensatedReplay(){Fixture f=new Fixture(0);f.saga.create(7,"request-00000001",request());Map<String,Object>drift=new HashMap<>(request());drift.put("playVersion","chengdu2001-v1.0.1");assertThrows(RuntimeException.class,()->f.saga.create(7,"request-00000001",drift));Map<String,Object>forged=new HashMap<>(request());forged.put("winner",7);assertThrows(RuntimeException.class,()->f.saga.create(7,"request-00000002",forged));}
 @Test void rejectsCompatibilityGameIdBeforeBillingOrRoomRegistration(){Fixture f=new Fixture(0);Map<String,Object>legacy=new HashMap<>(request());legacy.put("gameId",516);legacy.put("playVersion","legacy-equivalent-1");HallError error=assertThrows(HallError.class,()->f.saga.create(7,"request-00000003",legacy));assertEquals("HALL_IDENTITY_NOT_CURRENT_PUBLISHED",error.code());assertEquals(0,f.billing.reserve);assertEquals(0,f.rooms.register);}
 @Test void ruleRevisionIsDurableAndPartOfIdempotency(){Map<String,Object>source=request();RoomCreateSaga.Command command=RoomCreateSaga.Command.parse(7,"request-00000011",source);assertEquals(source.get("ruleRevision"),command.requestBody().get("ruleRevision"));Map<String,Object>changed=new HashMap<>(source);changed.put("ruleRevision",Map.of("classificationRegionCode","SC","releaseId",3L,"indexGeneration",8L,"sourceHash","sha256:rules-v1"));assertNotEquals(command.requestHash(),RoomCreateSaga.Command.parse(7,"request-00000011",changed).requestHash());}
 @Test void rejectsMissingOrInvalidRuleRevision(){Map<String,Object>missing=new HashMap<>(request());missing.remove("ruleRevision");assertEquals("HALL_RULE_REVISION_REQUIRED",assertThrows(HallError.class,()->RoomCreateSaga.Command.parse(7,"request-00000012",missing)).code());Map<String,Object>invalid=new HashMap<>(request());invalid.put("ruleRevision",Map.of("classificationRegionCode","SC","releaseId",0,"indexGeneration",7,"sourceHash",""));assertEquals("HALL_INVALID_RULE_REVISION",assertThrows(HallError.class,()->RoomCreateSaga.Command.parse(7,"request-00000013",invalid)).code());}
 @Test void clubScopeIsDurableAndPartOfIdempotencyHash(){Fixture f=new Fixture(0);Map<String,Object>club=new HashMap<>(request());club.put("scope",Map.of("type","CLUB","clubId",19L,"templateCode","default"));f.saga.create(7,"request-00000003",club);assertEquals(19L,f.store.command.scope().clubId());assertEquals("CLUB",f.store.command.scope().type());Map<String,Object>drift=new HashMap<>(club);drift.put("scope",Map.of("type","CLUB","clubId",20L,"templateCode","default"));assertThrows(RuntimeException.class,()->f.saga.create(7,"request-00000003",drift));}
 @Test void rejectsInvalidScopeAndRegionRouting(){Map<String,Object>personal=new HashMap<>(request());personal.put("scope",Map.of("type","PERSONAL","clubId",1));assertThrows(RuntimeException.class,()->RoomCreateSaga.Command.parse(7,"request-00000004",personal));Map<String,Object>region=new HashMap<>(request());region.put("regionCode","SC");assertThrows(RuntimeException.class,()->RoomCreateSaga.Command.parse(7,"request-00000005",region));}
 @Test void onlyTrustedBootstrapCanMarkClubTemplateEntry(){Map<String,Object>club=new HashMap<>(request());club.put("scope",Map.of("type","CLUB","clubId",19L,"templateCode","LS201-2"));club.put("_creationOrigin","CLUB_TEMPLATE_ENTRY");Fixture publicEntry=new Fixture(0);publicEntry.saga.create(7,"request-00000006",club);assertEquals(RoomCreateSaga.CreationOrigin.PUBLIC,publicEntry.store.command.creationOrigin());Fixture trustedEntry=new Fixture(0);trustedEntry.saga.createClubTemplate(7,"request-00000007",club);assertEquals(RoomCreateSaga.CreationOrigin.CLUB_TEMPLATE_ENTRY,trustedEntry.store.command.creationOrigin());assertEquals("CLUB_TEMPLATE_ENTRY",trustedEntry.store.command.requestBody().get("_creationOrigin"));}
 private static Map<String,Object>request(){return Map.of("roomId",99L,"gameId",2001,"playVersion","chengdu2001-v1.0.0","clientVersion","3.8.8","stateVersion",1L,"rules",Map.of("rounds",8),"ruleRevision",Map.of("classificationRegionCode","SC","releaseId",3L,"indexGeneration",7L,"sourceHash","sha256:rules-v1"));}
 private static final class Fixture{final Memory store=new Memory();final Port billing=new Port(),rooms=new Port(),authority=new Port();final RoomCreateSaga saga;Fixture(int fail){this(fail,command->command);}Fixture(int fail,RoomCreateSaga.RuleNormalizer normalizer){saga=new RoomCreateSaga(store,new RoomCreateSaga.BillingPort(){public void reserve(RoomCreateSaga.Command c){billing.reserve++;billing.lastRules=c.rules();if(fail==1)throw new IllegalStateException("injected");}public void confirm(RoomCreateSaga.Command c){billing.confirm++;}public void release(RoomCreateSaga.Command c){billing.release++;}},new RoomCreateSaga.RoomPort(){public void register(RoomCreateSaga.Command c){rooms.register++;rooms.lastRules=c.rules();if(fail==2)throw new IllegalStateException("injected");}public Map<String,Object>confirm(RoomCreateSaga.Command c,long v){if(fail==4)throw new IllegalStateException("injected");return Map.of("roomId",c.roomId(),"state","OPEN","stateVersion",v,"playVersion",c.playVersion());}public void remove(RoomCreateSaga.Command c){rooms.remove++;}},normalizer,new RoomCreateSaga.AuthorityPort(){public Map<String,Object>create(RoomCreateSaga.Command c){authority.create++;if(fail==3)throw new IllegalStateException("injected");return lease(c);}public Map<String,Object>recover(RoomCreateSaga.Command c){authority.recover++;return lease(c);}public Map<String,Object>destroy(RoomCreateSaga.Command c,Map<String,Object>expectedLease){authority.remove++;return expectedLease;}public void remove(RoomCreateSaga.Command c,long fence){throw new AssertionError("legacy remove must not be called");}private Map<String,Object>lease(RoomCreateSaga.Command c){return Map.of("roomId",c.roomId(),"gameId",c.gameId(),"playVersion",c.playVersion(),"gameCode","test","roomInstanceId","instance-1","lifecycleEpoch",1L,"fencingToken",1L,"stateVersion",0L,"route","ws://local","nodeId","test");}});}}
 private static final class Port{int reserve,confirm,release,register,remove,create,recover;Map<String,Object>lastRules=Map.of();}
 private static final class Memory implements RoomCreateSaga.Store{RoomCreateSaga.State state;RoomCreateSaga.Command command;public RoomCreateSaga.State begin(RoomCreateSaga.Command c){command=c;if(state==null)state=new RoomCreateSaga.State(c.requestId(),c.requestHash(),RoomCreateSaga.Step.STARTED,1,Map.of());return state;}public RoomCreateSaga.State find(String id){return state;}public RoomCreateSaga.State advance(String id,long v,RoomCreateSaga.Step step,Map<String,Object>out){return state=new RoomCreateSaga.State(id,state.requestHash(),step,v+1,out==null?state.response():out);}public void fail(String id,long v,RoomCreateSaga.Step step,RoomCreateSaga.Step origin,String reason){state=new RoomCreateSaga.State(id,state.requestHash(),step,v+1,state.response(),origin);}public boolean acquire(String id,String token,Duration lease){return true;}}
}
